<template>
    <section>
        <div class="lead-page-title"><div><h2>合作商户</h2><p>先保存门店资料，再绑定会员、接入 ERP；不必一次准备全部授权。</p></div><el-button type="primary" :icon="Plus" @click="open()">添加商户</el-button></div>
        <el-alert v-if="error || providerError" :title="error || providerError" type="error" show-icon :closable="false" class="lead-error-banner" />
        <div class="lead-card lead-table-card"><HsxSearchPanel :collapsible="false" :show-layout-switch="false"><el-form inline class="lead-search" @submit.prevent="search"><el-form-item label="商户 / 联系人"><el-input v-model="query.keyword" clearable placeholder="搜索店铺、联系人或手机号" @keyup.enter="search" @clear="search" /></el-form-item><el-form-item label="准备状态"><el-select v-model="query.ready_state" clearable placeholder="全部状态"><el-option v-for="(name, value) in readyLabels" :key="value" :label="name" :value="value" /></el-select></el-form-item><el-form-item label="ERP 渠道"><el-select v-model="query.provider" clearable placeholder="全部渠道"><el-option v-for="item in providers" :key="item.key" :label="item.name" :value="item.key" /></el-select></el-form-item><el-form-item><el-button :icon="Search" @click="search">查询</el-button><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button></el-form-item></el-form></HsxSearchPanel>
            <HsxTable :columns="columns" :data="rows" :loading="loading" empty-text="尚无商户，先添加门店资料即可"><template #merchant="{ row }"><div class="lead-cell"><strong>{{ row.name }}</strong><small>{{ region(row) }}</small></div></template><template #contact="{ row }"><div class="lead-cell"><strong>{{ row.contact_name }}</strong><small>{{ row.mobile }}</small></div></template><template #ready="{ row }"><div class="lead-cell"><el-tag :type="row.ready_state === 'ready' ? 'success' : row.ready_state === 'attention' ? 'danger' : 'warning'">{{ readyLabels[row.ready_state] || '待完善资料' }}</el-tag><small>{{ row.ready_reason }}</small></div></template><template #connection="{ row }"><div class="lead-cell"><strong>{{ providerName(row.provider) }}</strong><small>{{ row.connection_id ? syncLabel(row.last_sync_status) : '与商户资料独立保存' }}</small><small v-if="row.connection_id">{{ time(row.last_sync_at) }}</small></div></template><template #actions="{ row }"><div class="lead-actions"><el-button link type="primary" @click="open(row.id)">{{ row.ready_state === 'member_required' ? '绑定会员' : '资料' }}</el-button><el-button link type="primary" @click="connect(row)">{{ row.connection_id ? '接入管理' : '接入 ERP' }}</el-button><el-button v-if="row.connection_id" link type="primary" :disabled="Number(row.status) !== 1" @click="sync(row.id)">{{ row.ready_state === 'sync_required' ? '首次同步' : '同步' }}</el-button><el-button v-if="row.connection_id" link @click="openSettings(row)">周期</el-button><el-button v-if="row.last_run_id || row.active_run_id" link @click="showRun(row.last_run_id || row.active_run_id)">进度</el-button></div></template></HsxTable><div class="lead-pagebar"><HsxPagination v-model:current-page="query.page" v-model:page-size="query.limit" :total="total" @change="load" /></div>
        </div>
        <HsxDrawer v-model="visible" :title="form.id ? '商户资料' : '添加合作商户'" subtitle="只保存门店、服务范围和会员绑定，不修改 ERP 或中断同步。" size="md" :body-loading="detailLoading" :confirm-loading="saving">
            <el-alert v-if="detailError" :title="detailError" type="error" :closable="false" class="lead-error-banner" />
            <el-form v-if="!detailLoading && !detailError" ref="formRef" :model="form" :rules="rules" label-position="top" class="lead-form" :disabled="saving"><el-form-item label="商户 / 门店名称" prop="name"><el-input v-model.trim="form.name" maxlength="100" /></el-form-item><div class="lead-grid-2"><el-form-item label="联系人" prop="contact_name"><el-input v-model.trim="form.contact_name" maxlength="50" /></el-form-item><el-form-item label="联系电话" prop="mobile"><el-input v-model.trim="form.mobile" maxlength="30" /></el-form-item></div><el-form-item label="门店地区" prop="district_id"><RegionSelect v-model="area" /></el-form-item><el-form-item label="详细地址"><el-input v-model.trim="form.address" maxlength="255" /></el-form-item><el-form-item label="服务范围"><el-select v-model="serviceScope"><el-option label="优先按所在地推荐（默认）" value="default" /><el-option label="仅本区县" value="district" /><el-option label="整个城市" value="city" /><el-option label="整个省份" value="province" /><el-option v-if="serviceScope === 'custom'" label="保留已登记范围" value="custom" /></el-select><p class="lead-muted">使用框架省市区，不使用地图或估算距离。</p></el-form-item><el-form-item label="商户会员身份（可稍后绑定）"><el-select v-model="form.member_id" filterable remote clearable :remote-method="loadMembers" :loading="membersLoading" placeholder="搜索现有会员昵称或手机号" @visible-change="value => value && loadMembers()"><el-option v-for="member in members" :key="member.member_id || member.id" :value="Number(member.member_id || member.id)" :label="`${member.nickname || '未设置昵称'} · ${member.mobile || `会员 #${member.member_id || member.id}`}`" /></el-select><p class="lead-muted">使用原有会员登录；未绑定可先建档，但不能派单。</p><span v-if="membersError" class="lead-error">{{ membersError }}</span></el-form-item><el-form-item label="合作状态"><el-radio-group v-model="form.status"><el-radio :value="1">合作中</el-radio><el-radio :value="0">暂停合作</el-radio></el-radio-group></el-form-item><el-form-item label="运营备注"><el-input v-model="form.remark" type="textarea" :rows="3" maxlength="1000" /></el-form-item></el-form>
            <template #footer><el-button :disabled="saving" @click="visible = false">取消</el-button><el-button :loading="saving" :disabled="detailLoading || !!detailError" @click="save(false)">仅保存资料</el-button><el-button type="primary" :loading="saving" :disabled="detailLoading || !!detailError" @click="save(true)">保存并接入 ERP</el-button></template>
        </HsxDrawer>
        <ConnectionWizard v-model="connectionVisible" :merchant-id="selectedMerchant.id || 0" :merchant-name="selectedMerchant.name || ''" @changed="load" @sync="sync" />
        <SyncProgressDrawer v-model="runVisible" :run-id="runId" @changed="load" />
        <HsxDrawer v-model="settingsVisible" title="库存同步设置" subtitle="与门店资料独立保存，不重新提交 ERP 凭据。" size="sm" :body-loading="settingsLoading" show-footer :confirm-loading="settingsSaving" confirm-text="保存同步周期" @confirm="saveSettings"><el-alert v-if="settingsError" :title="settingsError" type="error" :closable="false" class="lead-error-banner" /><el-form label-position="top" :disabled="settingsLoading || settingsSaving"><el-form-item label="自动同步"><el-switch v-model="settings.enabled" /></el-form-item><el-form-item label="间隔（分钟）"><el-input-number v-model="settings.interval_minutes" :min="15" :max="1440" :precision="0" /></el-form-item><p class="lead-muted">默认 60 分钟；关闭后仍可手动同步。服务器计划任务需管理员启用。</p></el-form></HsxDrawer>
    </section>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox, type FormInstance, type FormRules } from 'element-plus'
import { Plus, Refresh, Search } from '@element-plus/icons-vue'
import HsxDrawer from '@/addon/hsx_components/components/HsxDrawer/index.vue'
import HsxTable from '@/addon/hsx_components/components/HsxTable/index.vue'
import HsxSearchPanel from '@/addon/hsx_components/components/HsxSearchPanel/index.vue'
import HsxPagination from '@/addon/hsx_components/components/HsxPagination/index.vue'
import RegionSelect from './RegionSelect.vue'
import ConnectionWizard from './ConnectionWizard.vue'
import SyncProgressDrawer from './SyncProgressDrawer.vue'
import { serviceScopeFor } from '../../composables/serviceScope'
import * as api from '../../api'
import { errorText, readyLabels, region, syncLabel, time, useLeadList, type Row } from '../../composables/useLeadUi'
const props = withDefaults(defineProps<{ initialFilter?: Row }>(), { initialFilter: () => ({}) })
const { rows, total, loading, error, query, load, search } = useLeadList(api.getMerchants, { provider: '', ready_state: props.initialFilter.ready_state || '' })
const columns = [{ prop: 'name', label: '商户 / 地区', slot: 'merchant', minWidth: 190 }, { prop: 'contact_name', label: '联系人', slot: 'contact', minWidth: 145 }, { prop: 'ready_state', label: '准备状态 / 下一步', slot: 'ready', minWidth: 200 }, { prop: 'provider', label: 'ERP / 同步', slot: 'connection', minWidth: 165 }, { prop: 'actions', label: '操作', slot: 'actions', minWidth: 270, fixed: 'right' as const }]
const providers = ref<Row[]>([]), providerError = ref('')
const providerName = (value: string) => providers.value.find(item => item.key === value)?.name || value || '尚未接入 ERP'
const empty = () => ({ id: 0, name: '', contact_name: '', mobile: '', province_id: 0, city_id: 0, district_id: 0, province_name: '', city_name: '', district_name: '', address: '', member_id: undefined as number | undefined, status: 1, remark: '', service_areas: [] as Row[] })
const form = reactive<Row>(empty()), formRef = ref<FormInstance>(), visible = ref(false), saving = ref(false), detailLoading = ref(false), detailError = ref(''), serviceScope = ref('default')
const members = ref<Row[]>([]), membersLoading = ref(false), membersError = ref('')
const originalMemberId = ref(0), originalStatus = ref(1)
const area = computed({ get: () => ({ province_id: form.province_id, city_id: form.city_id, district_id: form.district_id }), set: value => Object.assign(form, value) })
const rules: FormRules = { name: [{ required: true, message: '请填写门店名称', trigger: 'blur' }], contact_name: [{ required: true, message: '请填写联系人', trigger: 'blur' }], mobile: [{ required: true, message: '请填写联系电话', trigger: 'blur' }], district_id: [{ validator: (_rule, _value, callback) => form.province_id && form.city_id && form.district_id ? callback() : callback(new Error('请选择完整省、市、区县')), trigger: 'change' }] }
let detailSequence = 0, memberSequence = 0
async function open(id = 0) { const token = ++detailSequence; Object.assign(form, empty()); serviceScope.value = 'default'; originalMemberId.value = 0; originalStatus.value = 1; visible.value = true; detailError.value = ''; detailLoading.value = !!id; if (!id) return; try { const result = await api.getMerchant(id); if (token !== detailSequence) return; const row = result.data; for (const key of Object.keys(empty())) if (row[key] !== undefined) form[key] = row[key]; form.status = Number(row.status); originalStatus.value = Number(row.status); originalMemberId.value = Number(row.member_id || 0); form.member_id = row.member_id ? Number(row.member_id) : undefined; serviceScope.value = serviceScopeFor(row.service_areas || [], row); if (form.member_id) members.value = [{ member_id: form.member_id, nickname: row.member_name || `会员 #${form.member_id}`, mobile: row.member_mobile || '' }] } catch (cause) { if (token === detailSequence) detailError.value = errorText(cause, '商户资料加载失败。') } finally { if (token === detailSequence) detailLoading.value = false } }
async function loadMembers(keyword = '') { const token = ++memberSequence; membersLoading.value = true; membersError.value = ''; try { const result = await api.getMembers(keyword); if (token === memberSequence) members.value = Array.isArray(result.data) ? result.data : result.data.data || [] } catch (cause) { if (token === memberSequence) membersError.value = errorText(cause, '会员列表加载失败。') } finally { if (token === memberSequence) membersLoading.value = false } }
async function save(next: boolean) { if (!await formRef.value?.validate().catch(() => false)) return; if (form.id && originalMemberId.value !== Number(form.member_id || 0)) { try { await ElMessageBox.confirm('更换后原会员将失去本商户入口，新绑定会员可以查看本商户的工单、库存和佣金。确认已核对归属吗？', '确认更换商户会员', { type: 'warning', confirmButtonText: '确认更换' }) } catch { return } }; saving.value = true; const service_areas = serviceScope.value === 'custom' ? form.service_areas : serviceScope.value === 'default' ? [] : [{ province_id: form.province_id, city_id: serviceScope.value === 'province' ? 0 : form.city_id, district_id: serviceScope.value === 'district' ? form.district_id : 0 }]; try { const result = await api.saveMerchant({ ...form, service_areas, member_id: form.member_id || 0 }); visible.value = false; ElMessage.success(Number(form.status) === 0 ? '合作已暂停，未来自动同步已关闭；重新启用后需手动恢复周期' : originalStatus.value === 0 ? '合作已恢复，请在周期设置中手动恢复自动同步' : '商户资料已保存，不重新提交 ERP 授权'); await load(); if (next) connect({ id: result.data.id || form.id, name: form.name }) } catch (cause) { ElMessage.error(errorText(cause, '保存失败，请检查资料。')) } finally { saving.value = false } }
const selectedMerchant = ref<Row>({}), connectionVisible = ref(false), runVisible = ref(false), runId = ref(0)
function connect(row: Row) { selectedMerchant.value = row; connectionVisible.value = true }
function showRun(id: number) { runId.value = Number(id); runVisible.value = true }
async function sync(id: number) { try { const result = await api.syncMerchant(Number(id)); showRun(result.data.run_id); await load() } catch (cause) { ElMessage.error(errorText(cause, '同步未启动，请在接入管理中检查授权。')) } }
const settingsVisible = ref(false), settingsLoading = ref(false), settingsSaving = ref(false), settingsError = ref(''), settings = reactive({ enabled: true, interval_minutes: 60 })
async function openSettings(row: Row) { selectedMerchant.value = row; settingsVisible.value = true; settingsLoading.value = true; settingsError.value = ''; try { const result = await api.getConnection(row.id); settings.enabled = !!result.data.enabled; settings.interval_minutes = Number(result.data.interval_minutes || 60) } catch (cause) { settingsError.value = errorText(cause, '设置读取失败。') } finally { settingsLoading.value = false } }
async function saveSettings() { if (settingsLoading.value || settingsError.value) return; settingsSaving.value = true; try { await api.saveSyncSettings(selectedMerchant.value.id, { ...settings }); settingsVisible.value = false; ElMessage.success('同步周期已保存'); await load() } catch (cause) { settingsError.value = errorText(cause, '同步周期未保存。') } finally { settingsSaving.value = false } }
onBeforeUnmount(() => { detailSequence++; memberSequence++ })
onMounted(async () => { void load(); try { const result = await api.getProviders(); providers.value = result.data.items || [] } catch (cause) { providerError.value = errorText(cause, 'ERP 选项加载失败，仍可维护商户资料。') } })
</script>
